const ThemeContext = createContext<"light" | "dark">("light")

function App() {
  return <ThemeContext value="dark"><Toolbar /></ThemeContext>
}
function Toolbar() {
  const theme = useContext(ThemeContext) // "dark"
  return <div className={theme}>…</div>
}

type Action = { type: "added"; text: string } | { type: "removed"; id: number }
function todos(state: Todo[], action: Action): Todo[] {
  switch (action.type) {
    case "added": return [...state, { id: state.length + 1, text: action.text }]
    case "removed": return state.filter(t => t.id !== action.id)
  }
}

